def _card(icon: str, title: str, copy: str, accent: str, status: str, tags: list[str]) -> str:
    chips = "".join(f"<span>{tag}</span>" for tag in tags)
    return f"""<article class='card' style='--accent:{accent}'><div class='icon'>{icon}</div><h3>{title}</h3><p>{copy}</p><span class='status'>{status}</span><div class='featurelist'>{chips}</div></article>"""


@router.get("/brand/pulsar-frequency-house-logo.svg", include_in_schema=False)
def brand_logo():
    return FileResponse(LOGO_PATH, media_type="image/svg+xml", filename="pulsar-frequency-house-logo.svg")


